import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`tiktok-shop-gtm`,heroTitle:`Launch on TikTok Shop without an agency`,heroSubtitle:`Perplexity Computer researches winning TikTok Shop strategies, identifies creator angles, and builds your full GTM plan — automatically.`,inputUrlCta:`Build my GTM plan`,inputUrlPlaceholder:`yourproduct.com`,inputUrlPrefill:`Go to {url} and analyze the product, pricing, brand positioning, and target audience. Then build me a complete TikTok Shop go-to-market plan without needing an agency. 1) Research 10 winning TikTok Shop products in the same or adjacent categories — note their pricing, creator strategies, content formats, and estimated sales volume. 2) Identify 5 creator angles and content hooks that would work for this specific product, with example scripts and talking points for each. 3) Draft affiliate outreach messaging — a cold DM template, an email template, and a TikTok Shop affiliate listing description that attracts creators. 4) Build a unit economics model covering product cost, TikTok Shop commission, affiliate commission, shipping, and ad spend — calculate break-even ROAS and target CPA. 5) Deliver a 30-60-90 day GTM roadmap with specific weekly milestones, KPI targets, and budget allocation across organic, affiliate, and paid. 6) Include a competitor pricing and positioning matrix so I can see exactly where my product fits in the TikTok Shop landscape.`,heroOverlaySteps:[`Analyzing your product, pricing, and target audience`,`Researching winning TikTok Shop strategies in your category`,`Modeling unit economics and affiliate commission structures`,`GTM roadmap, creator scripts, and KPI targets — ready to execute`],generatingSteps:[`Visiting {url} to extract product details, pricing, and brand positioning`,`Designing an agent to research top-performing TikTok Shop products in your category`,`Configuring creator angle identification, affiliate messaging, and unit economics modeling`,`Setting up your 30-60-90 day GTM roadmap with KPI targets and budget allocation`],featureSectionTitle:`From product URL to TikTok Shop GTM plan`,featureCardTitles:[`Connects to your ecommerce stack`,`Outputs you can execute`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Shopify, Google Sheets, Notion, Slack, Airtable — Computer pulls your product data and delivers your GTM plan straight into the tools you already use.`,`Competitor landscape matrix. Creator outreach scripts. Affiliate messaging templates. Unit economics model. A 30-60-90 day roadmap with weekly KPI targets.`],capabilitySectionTitle:`Your TikTok Shop strategist, on autopilot`,capabilitySectionSubtitle:`Paste your product URL, step away, come back to a full launch plan.`,capabilityCards:[{title:`Category Research`,description:`Computer can analyze winning TikTok Shop products in your category — pricing, creator strategies, content formats, and estimated sales volume.`},{title:`Creator Angles`,description:`Computer can identify the content hooks and creator types that drive sales for products like yours — with draft scripts and talking points for each.`},{title:`Affiliate Messaging`,description:`Computer can write cold DM templates, email outreach, and affiliate listing descriptions that attract the right creators to your product.`},{title:`Connect Your Tools`,description:`Computer can pull from Shopify, Google Sheets, Notion, Airtable, and Slack — build workflows across your entire ecommerce and planning stack.`},{title:`Remember & Learn`,description:`Computer can remember your product catalog, past creator partnerships, and campaign results — so every GTM plan builds on what's already working.`},{title:`Monitor & Alert`,description:`Computer can track competitor TikTok Shop activity weekly and flag new creator trends, pricing shifts, or category opportunities as they emerge.`}]});export{t as default};
